for (const item of candidateUrls) {
  try {
    const res = await tool.fetch_url({ url: item.url });
    const html = res.body;

    // Extract title
    const titleMatch = html.match(/<title data-rh="true">(.*?)<\/title>/i) || html.match(/<title>(.*?)<\/title>/i);
    const titleText = titleMatch ? titleMatch[1].replace(/ \| Netflix Official Site/i, '').replace(/Watch /i, '').trim() : item.name;

    // Extract description
    const descMatch = html.match(/<meta data-rh="true" content="(.*?)" name="description"/i) || html.match(/<meta name="description" content="(.*?)"/i);
    let desc = descMatch ? descMatch[1] : '';
    desc = desc.replace(/Watch trailers &amp; learn more\./i, '').replace(/Watch trailers & learn more\./i, '').trim();

    // Extract seasons or episodes
    const seasonMatch = html.match(/(\d+)\s+Season[s]?/i);
    const limitedMatch = html.match(/Limited Series/i);

    // Extract genres/tags
    const genreMatch = html.match(/<meta name="keywords" content="(.*?)"/i);

    results.push({
      name: titleText,
      url: item.url,
      hook: desc,
      seasonInfo: limitedMatch ? "Limited Series" : (seasonMatch ? seasonMatch[0] : "Not explicitly stated on page"),
      status: res.status
    });
  } catch (e) {
    results.push({ name: item.name, url: item.url, error: e.message });
  }
}

