async function searchBingForRatings(title) {
  const query = `${encodeURIComponent(title)} tv series imdb rotten tomatoes`;
  await tool.navigate({ tabId, url: `https://www.bing.com/search?q=${query}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });

  const result = await browserjs(tabId, () => {
    function decodeBingUrl(href) {
      try {
        const url = new URL(href);
        const u = url.searchParams.get("u");
        if (u && u.startsWith("a1")) {
          let b64 = u.slice(2);
          // Base64URL decode
          b64 = b64.replace(/-/g, "+").replace(/_/g, "/");
          while (b64.length % 4) b64 += "=";
          return atob(b64);
        }
      } catch(e) {}
      return href;
    }

    const allLinks = Array.from(document.querySelectorAll('a[href]')).map(a => decodeBingUrl(a.href));
    const imdbLink = allLinks.find(u => u.includes('imdb.com/title/')) || null;
    const rtLink = allLinks.find(u => u.includes('rottentomatoes.com/tv/')) || null;

    // Also look for rating text in snippets
    const bodyText = document.body.innerText;
    const imdbScoreMatch = bodyText.match(/(\d\.\d)\/10\s*·?\s*IMDb/i) || bodyText.match(/IMDb\s*·?\s*(\d\.\d)\/10/i) || bodyText.match(/Rating:\s*(\d\.\d)\/10/i);
    const rtScoreMatch = bodyText.match(/(\d+)%\s*·?\s*Rotten Tomatoes/i) || bodyText.match(/Rotten Tomatoes\s*·?\s*(\d+)%/i);

    return {
      imdbLink,
      rtLink,
      imdbScoreText: imdbScoreMatch ? imdbScoreMatch[1] : null,
      rtScoreText: rtScoreMatch ? rtScoreMatch[1] : null,
      snippetSample: bodyText.slice(0, 1000)
    };
  });

  return result;
}

